);
alter table public.ifund_volunteer_opportunity enable row level security;
revoke all on public.ifund_volunteer_opportunity from public, anon, authenticated;

-- VolunteerSignup - User applications or signups for campaign and community volunteer roles.
create table if not exists public.ifund_volunteer_signup (
  id text primary key,
  "opportunity_id" text,
  "community_id" text,
  "user_id" text,
  "user_name" text,
  "description" text,
  created_date timestamptz,
  updated_date timestamptz,
  created_by_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
