);
alter table public.ifund_volunteer_signup enable row level security;
revoke all on public.ifund_volunteer_signup from public, anon, authenticated;

-- WebhookEvent - Provider webhook processing receipts and idempotency state for safe retries, authenticity checks, and reconciliation.
create table if not exists public.ifund_webhook_event (
  id text primary key,
  "source" text,
  "event_key" text,
  "event_type" text,
  "state" text,
  "canonical_operation_id" text,
  "attempt_count" numeric default 1,
  "last_error" text,
  "financial_applied_at" text,
  "side_effects_completed_at" text,
  "processed_at" text,
  "description" text,
  created_date timestamptz,
  updated_date timestamptz,
  created_by_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  source_system text not null default 'base44',
  migrated_at timestamptz not null default now()
  ,constraint ifund_webhook_event_state_enum check ("state" is null or "state" in ('claimed', 'financial_applied', 'side_effects_complete', 'nonfinancial_complete', 'failed'))
);
alter table public.ifund_webhook_event enable row level security;
revoke all on public.ifund_webhook_event from public, anon, authenticated;

-- Withdrawal - User withdrawal request and processing state; confirmed payout amounts must derive from authoritative financial records.
create table if not exists public.ifund_withdrawal (
  id text primary key,
  "owner_user_id" text,
  "user_name" text,
  "campaign_id" text,
  "campaign_title" text,
  "gross_amount" numeric,
  "platform_fee" numeric,
  "net_amount" numeric,
  "paypal_email" text,
  "covered_donation_ids" jsonb,
  "covered_holding_entry_ids" jsonb,
  "status" text,
  "canonical_operation_key" text,
  "canonical_reservation_id" text,
  "canonical_ledger_entry_id" text,
  "payout_batch_id" text,
  "provider_sender_batch_id" text,
  "review_note" text,
  "processed_at" text,
  "description" text,
  created_date timestamptz,
  updated_date timestamptz,
  created_by_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  source_system text not null default 'base44',
  migrated_at timestamptz not null default now()
  ,constraint ifund_withdrawal_status_enum check ("status" is null or "status" in ('pending', 'reserving', 'processing', 'under_review', 'provider_status_unknown', 'reconciliation_pending', 'reservation_release_pending', 'paid', 'failed', 'cancelled'))
);
alter table public.ifund_withdrawal enable row level security;
revoke all on public.ifund_withdrawal from public, anon, authenticated;

